# Generated by OrchestKit Claude Plugin
# Created: 2026-07-30

"""Which error-text fragments the suite is allowed to assert (plan T1.7).

`assert_refusal(contains=…)` is the only helper in this suite that looks at wire text, and
this module is what keeps that privilege honest: every `contains=` literal must appear
verbatim in a module this repo ships. Framework wording — FastMCP's envelope, pydantic's
validation prose — belongs to a dependency pinned as a *range*, so asserting it means one
`pip install -U` reds the suite without a single thing being wrong with this server.

Pure functions over an AST, deliberately: no Docker, no imports of the code under test, so
the guard runs in the same second as the linters.
"""

from __future__ import annotations

import ast
from dataclasses import dataclass
from pathlib import Path

HELPER = "assert_refusal"
KEYWORD = "contains"
# A non-literal `contains=` — an f-string, a variable, a `.format()` — would let arbitrary
# wording through while still looking compliant, so it is recorded as a violation rather than
# skipped. Not a valid fragment either way: it can never be found in a product module.
NOT_A_LITERAL = "<not a literal>"


@dataclass(frozen=True)
class Fragment:
    """One asserted piece of wire text, and where the suite asserts it."""

    origin: str
    lineno: int
    value: str


def product_sources(repo_root: Path) -> dict[str, str]:
    """Every root-level module, read from disk.

    Derived rather than listed. The Dockerfile's COPY list is an explicit enumeration and has
    shipped a broken image twice by falling behind the tree; a hardcoded list here would fall
    behind the same way, and the failure mode is worse — a *silent* one, where a legitimate
    fragment is reported as unauthored and someone deletes the guard to make it stop.
    """
    return {path.name: path.read_text(encoding="utf-8") for path in sorted(repo_root.glob("*.py"))}


def scan_source(tree: ast.AST, origin: str) -> list[Fragment]:
    """Every `contains=` handed to the refusal helper in one parsed module."""
    found: list[Fragment] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or _called_name(node.func) != HELPER:
            continue
        for keyword in node.keywords:
            if keyword.arg != KEYWORD:
                continue
            value = keyword.value
            literal = value.value if isinstance(value, ast.Constant) else None
            found.append(
                Fragment(
                    origin=origin,
                    lineno=node.lineno,
                    value=literal if isinstance(literal, str) else NOT_A_LITERAL,
                )
            )
    return found


def scan_tree(root: Path) -> list[Fragment]:
    """The same scan over every Python file in the suite."""
    found: list[Fragment] = []
    for path in sorted(root.rglob("*.py")):
        if "__pycache__" in path.parts:
            continue
        source = path.read_text(encoding="utf-8")
        found.extend(scan_source(ast.parse(source), str(path.relative_to(root))))
    return found


def unauthored(fragments: list[Fragment], sources: dict[str, str]) -> list[Fragment]:
    """The fragments no product module contains — i.e. the ones nobody here wrote."""
    return [
        fragment
        for fragment in fragments
        if not any(fragment.value in source for source in sources.values())
    ]


def _called_name(func: ast.expr) -> str | None:
    """`assert_refusal(...)` and `assertions.assert_refusal(...)` are the same call."""
    if isinstance(func, ast.Name):
        return func.id
    if isinstance(func, ast.Attribute):
        return func.attr
    return None
